/* Landfall — the key crew's own page (Lachlan, 2026-11-18; DESIGN.md "Twelve key crew", "The officer's page").
   Tap an officer on the People view and this is what opens: who they are when nothing is wrong (nature), how they are
   now, how they see the colony, how they see you, and what they make of each of the others. Every line is theirs and is
   checked against their section of VOICES.md. LF.profile(s, p) is a pure function of the state: no dice, nothing stored,
   no numbers shown. Lines never name a count, a date or another officer outside "on", so they stay true in any game.
   No DOM. */
(function () {
'use strict';
/* now: fine, spent (sent in person and resting), frayed (nerve), failing (health), hurt (laid up).
   colony: good, steady, hungry, low (morale), dread (something is pressing), grim (what the colony has done).
   you: four bands of regard, best first (LF.standing). on: the ten who are not this seat's other officer. */
const P = {
  solheim: {
    now: { fine: `"I'm fit and I'm on station, so give me an order, or I'll go out to the yard and check the work myself."`, spent: `"I've been grounded and I'm staying grounded, because a commander who falls over at muster costs the colony more than one who sits out a month. Put me back on the roster the day the clinic signs me off."`, frayed: `"I'm not sleeping, and I've logged it and decided it doesn't matter, because the work gets done either way. If it ever starts costing the colony people, I'll tell you myself."`, failing: `"My body's going and it won't come back, and that's a reading, not a complaint. I'll hold this chair as long as I can stand at it, and the day I can't you'll hear it from me before anyone else."`, hurt: `"I'm laid up and I don't like it, because every month I'm on my back the yard takes its orders from a messenger. Get me signed off and back on my feet."` },
    colony: { good: `"The stores are full and the crews are working, and that's the margin I've been waiting for, so we build now, before the season closes on us."`, steady: `"We're eating and we're standing, which is all I ask of a season, but it won't carry us through the next hard one unless we build faster than we have been."`, hungry: `"The ration's short and it stays short until the fields give more, so nobody gets an extra bowl. Anyone who wants to argue it can argue with a spade in their hands."`, low: `"They've stopped believing it'll be worth it, and I don't need them to believe, I need them at the wire and in the beds every morning. Give them work with an end they can see and most of them will follow it."`, dread: `"People are dying and I can't give you a cause yet, so I want every door counted and every body examined, and I want it done before the count goes up again."`, grim: `"We did what it took to keep this colony alive, and I'd make every one of those calls again. Every name it cost is in my book, and they stay there as long as the people they bought are still standing."` },
    you: [`"You make the call and you let it stand, which is more than most who've sat in that chair. Tell me what needs building and I'll have crews on it at first light."`, `"You decide slower than I would, but you decide, and I can fly with that. Keep the orders clear and I'll carry every one of them out."`, `"I've watched you put things to a vote that needed an answer, and every month of that costs the colony people it can't spare. Decide faster, or stand aside for someone who will."`, `"I'm still at my post because the colony needs a commander, and that has nothing to do with you. The day you stand between this colony and its survival, I'll go around you."`],
    on: { dahl: `"He's right more often than he's pleasant, and I'll take right. He locks everything and trusts nobody, which is the exact habit I want on the watch on this ground."`, kovacs: `"When he tells me how long a machine has got, I plan on it, because he's never once been wrong. He's worn out and he knows it, and I'd keep him on his feet in the shop if I had to prop him up myself."`, nakamura: `"She'll break an order for one patient and sleep fine afterward, and it costs the colony every time. I've never flown with a better doctor, so I put up with it, and I watch what leaves her shelves."`, yurbin: `"He'll walk straight at anything that moves past the wire if nobody stops him. I want his results, and I want him back inside the wire by dark, every time."`, estrada: `"He fasts when we're short, which is the one thing I'd never order anyone to do, and he still works every row he's given. The crops come in, so I leave him alone in the fields."`, zulu: `"He takes the worst of the night watch himself instead of handing it down, and he's wearing out because of it. I'd think more of him if he put someone else on the roster and saved his strength for the night we need it."`, halloran: `"She'll strip the lander for parts and call it a repair, and she gets every machine running again, which is why I haven't stopped her. The day I need that lander I'll want it whole, and she knows it, because I've told her."`, brandt: `"He tells me what the dying need and what the living can afford, and he never softens either one. He's the one on the council I'd trust to tell me I'm wrong, though he hasn't changed an order of mine yet."`, iyer: `"She counts people the way I do, as a cost against what the colony gets back, so I never have to explain an order to her. I still read what she asks for before I sign it, because her heading and mine aren't always the same."`, waititi: `"He feeds the colony and he keeps the hall loud, and both are worth having. I've never laughed at one of his stories, and I've told him the work doesn't need me to."` } },
  dahl: {
    now: { fine: `"I'm perfectly well, which I'd find more reassuring if the whole place weren't so quiet, because in my experience quiet is just the planet taking its time about it."`, spent: `"They've told me to sit down and rest, so here I sit, and who's walking my wire tonight? People who don't know where it sags, which is a very relaxing thought."`, frayed: `"No, I'm not sleeping, and before you ask, I've no intention of pretending that I am, because somebody who's awake at night is a lot more use than somebody who isn't and gets surprised."`, failing: `"Don't look at me like that, I know what the ward says and I know it's got an end on it, so I'd rather you spent the time asking me what I've left undone than how I'm feeling."`, hurt: `"I'm laid up, I'm bored, and I'm fairly sure the watch is doing everything wrong without me, so if you want to make me feel better, you could tell me they're not."` },
    colony: { good: `"Everyone's fed and everyone's smiling, and I'm sure that's lovely, but I keep wondering what they think they've got to smile about, and who's got the thing they're going to want next."`, steady: `"We're getting by, which is what people say right before the thing they weren't watching comes through the gate, so I'm watching it anyway, since someone has to."`, hungry: `"People are loyal to a full bowl, and the bowls are getting thin, so I'd start thinking now about who's going to be holding the stores when everyone else notices."`, low: `"Nobody's got any fight left in them, and that's the worst time of all, because a tired crowd doesn't riot, it just quietly decides you're the problem and waits."`, dread: `"Something is killing us and nobody can say what, and I'd like it noted that I said from the start this place wasn't as empty as the survey made out, not that it helps anyone now."`, grim: `"We did what we did, and I'll sign for my share of it, but don't ask me to pretend that people look at each other the same way, because I see them not doing it every day on the wire."` },
    you: [`"You listen, you decide, and when it goes badly you don't go hunting for somebody to blame, which I'd have bet against when we came down, so I'll stand next to you and keep my objections for when they matter."`, `"You're not who I'd have picked, and you're not who I'd have feared either, so I'll do the work, I'll tell you when I think you're wrong, and we'll see how long that arrangement holds."`, `"I keep waiting for you to make the hard call, and you keep finding a kinder one, and I'd like to believe that's wisdom, but it's starting to look a lot like hoping."`, `"I stopped expecting anything from you a while back, so I'm here for the people behind the wire, and if that sounds like an insult, well, it was never meant as a compliment."`],
    on: { solheim: `"Jane's the only one up there who'd make the call I'd make, and I'd feel a lot better about that if she'd ever once looked as if it cost her something."`, kovacs: `"Jeremy tells you how long a thing has left and he's never been wrong, so when he says the gate won't last, I believe him, which is more than I can say for anyone with an opinion on the gate."`, nakamura: `"Andrea will break any order you give her for one patient with a good enough story, and I admire it, and I also keep a list of the orders she's broken, because someone ought to."`, yurbin: `"Mac goes out past the wire and comes back with something alive in a jar, delighted, and every time I think the only thing standing between us and whatever's in that jar is a latch."`, estrada: `"Samuel's the one person here I've never caught lying, and that worries me more than it should, because a man that honest has nothing to hide behind when it all goes wrong."`, achebe: `"Lucas gives a man a second chance and then looks at him sadly, and half the colony would rather be flogged, so in a way he's got the best system of the lot, and I'd never tell him."`, halloran: `"Roberta's been taking parts off the lander and thinks I haven't noticed, and I haven't said so yet, because a woman who can build anything out of nothing is worth a few missing bolts."`, brandt: `"Lou looks at me like he's reading what I had for breakfast off my face, and the bloody awful part is that he's usually right, so I keep out of his ward and he keeps out of my head."`, iyer: `"Michelle asked me for two of the watch and wouldn't say what for, and I've been wondering what she'd have done with them ever since, which I suspect was the whole point."`, waititi: `"Hamond sends soup up to the watch and tells the whole yard about it, and I'd call him a security risk on principle, except that the men on the wire would follow him into the water for it."` } },
  kovacs: {
    now: { fine: `"I'm all right, the knees are complaining like they always do, and the pumps are running sweeter than they've got any right to, so don't go looking for something to fix on my account."`, spent: `"You sent me out there and now you've sat me down, and I'll tell you what, I'd rather be under the old girl with a torch than staring at the wall being rested like a spare pump on a shelf."`, frayed: `"I'm not sleeping much, no, but that's the yard at night, it ticks and groans and I lie there working out which bit of it's about to go, so it's not as if I'm doing nothing."`, failing: `"Lou's told me my insides are going the way of my knees and I told him I've got a hundred things to keep running first, so ask me again when the water's sorted."`, hurt: `"I'm laid up and I hate it, and every time something clanks out there I'm half out of this cot before somebody pushes me back down, so tell them to stop letting it clank."` },
    colony: { good: `"Well, the water's steady and the stores are full and nobody's come to me with a broken thing since the last broken thing, which makes me nervous, but I'll take it."`, steady: `"We're getting by on patches and luck like we always do, and she'll hold as long as nobody gets creative with her, so it's about what I expected."`, hungry: `"The stores are short and everybody's looking at the fields like they could shout the crop up, and all I can do is keep the pumps and the cold room from failing us on top of it."`, low: `"People are dragging their feet round the yard and they leave tools lying in the mud, and when folks stop caring about the small stuff the big stuff breaks next."`, dread: `"I don't know what it is and I can't weld a door shut against something I can't see, but I've been through every machine we've got twice and it isn't any of them, and that's what frightens me."`, grim: `"I built a lot of what we did and I'd like to tell you I only turned the bolts, but I know what the bolts were for, and she doesn't run any smoother for it."` },
    you: [`"You ask before you cut anything and you listen when I say how long she's got left, and I've worked under people who couldn't manage either, so you've got my shift whenever you need it."`, `"You're all right, you let me do the job and you don't give speeches, and that's about all a mechanic can ask of anybody who signs the work orders."`, `"I don't like how fast you decide things, and every time I tell you it's going to cost us you sign it anyway, and then I'm the one underneath it at three in the morning."`, `"I'm not here for you any more, I'm here because the pumps and the power and the water don't run themselves, and if I walked off the yard people would be dead by the end of the season."`],
    on: { solheim: `"She makes the hard call and she doesn't flinch, which is more than I can say for me, but she's spending people the way you'd spend spares, and one day she's going to run out of the kind you can't make."`, dahl: `"He checks every lock twice a night and then he comes round to me to ask why the hinges squeak, so I give him a tin of grease and he gives me a look like I've poisoned him."`, nakamura: `"She'll break every rule in the book for a patient and then come down here and shout at me for the generator being cold, and honestly, she's earned the shouting."`, yurbin: `"He borrows my tools and brings them back with something growing on the handle, and I keep telling him I don't mind the borrowing, I mind the growing."`, estrada: `"He talks to the crops and he goes hungry on a fast day, and I get him fixing the pump, I really do, but somebody has to make him eat before he falls over the irrigation lines."`, achebe: `"He doesn't shout when something's broken, he just stands there looking let down, and I'd rather have shouting, because I can work through shouting."`, zulu: `"That lad takes the worst of the night watch himself and won't hear a word about it, and I've started leaving the lamps charged for him without saying anything, because that's about all he'd let me do."`, brandt: `"He told me straight that my knees are finished and he was right, which I resent, and he'll sit up all night with the dying without a word to anyone, which I don't, so I let him have the last say."`, iyer: `"She asks me for things that can't be undone and calls it a specification, and I always ask what it's for, and she always says it's not relevant, which is exactly why I always ask."`, waititi: `"He promises everybody more than we can build and then comes to me to find out how, and I grumble and I fix it, because the man feeds the whole yard and I'd be a poor sort if I let him down."` } },
  nakamura: {
    now: { fine: `"I'm fine, honestly, and it's kind of you to ask, but you didn't walk all the way down to the ward to check on me, so tell me who's sick."`, spent: `"I got told to rest, so I'm resting, and I hate every minute of it, because there are people in those beds asking for me by name and getting somebody else. I'll sit down when the ward's empty and not before, and you can tell whoever ordered it I said so."`, frayed: `"No, I'm not sleeping, and before you ask, yes, I know exactly what I'd tell a patient who said that to me. I keep seeing their faces when I shut my eyes, the ones I couldn't keep, and it'll pass if everyone stops fussing at me."`, failing: `"My own body's turning on me and I can't fix it, and I've sat on the other side of this bed with enough people to know exactly what's coming. I'll keep working until my hands won't let me, so please don't go finding somebody to take my place yet."`, hurt: `"I'm laid up and I'm furious about it, because I can't stand at the table and the people who need me are being patched by tired hands. Get me back on my feet quick, will you, or at least let me sit in the ward and shout at whoever's doing it wrong."` },
    colony: { good: `"Everybody's eating and the ward's half empty, and I stood in the doorway this morning and nearly cried because it was quiet. I want more of this, so don't you let anyone talk themselves into spending it on something stupid."`, steady: `"We're getting by, and I'll take getting by, because I've seen what the other thing looks like. But I'm still bandaging the same cuts and coughs I was bandaging before, so someone's cutting corners out in the yard and I'd like to know who."`, hungry: `"The ration is making people sick, you know that, and I'm the one watching the children's arms get thin and the old ones go grey around the mouth. Find me food, or at least don't sit there and tell me it's a hard choice, because I'm the one who has to look at them."`, low: `"Nobody's laughing anymore, and I can hear it from the ward, the whole place has gone quiet in a way I don't like at all. People who've given up don't heal, so whatever you can do to give them something to wake up for, please do it now."`, dread: `"Something is killing us and I can't tell you what, and I hate saying that out loud, because I'm supposed to know. I've opened up everything I can and I still can't find it, so please don't ask me to be calm about it, because the families can read my face."`, grim: `"I helped with what we did and I'll carry it, I'm not asking anyone to forgive me, but I can see it on every face that walks into the ward. We kept ourselves alive, I know, and I still can't get the smell of it out of my hands."` },
    you: [`"I'd follow you into the worst of it, and you know why? Because you actually come down and look at them before you decide, and most people in charge never do. Whatever you ask of me, you'll have it."`, `"You do the job and you listen when I shout, which is more than most of the people who ran my wards in Johannesburg ever managed. We'll argue again, I'm sure of it, but it'll be because I want you to get it right for them."`, `"I keep waiting for you to come down to the ward and see what your choices look like on a bed, and you haven't, and I don't understand it. Prove me wrong, because I'd honestly rather be wrong."`, `"I'm still here for the people in those beds, not for you, and don't you mistake the one for the other. Ask me for a thing I can do for them and I'll do it. Anything else, you can find somebody else."`],
    on: { solheim: `"Jane would trade one life for ten without blinking, and I've told her to her face that I'll stand in front of her before I let her do it to a name I know. She hates that I won't back down, and I've never once been sorry."`, dahl: `"Nolan sees a threat in every sick person who walks through my door, and I've had to throw him out of the ward more than once for it. I do understand where it comes from, and I'd still rather he'd just let me tend them in peace."`, kovacs: `"Jeremy walks on those knees all day and swears they're just stiff, and he's going to fall over in the yard one of these days and then I'll have to listen to him complain about the stretcher. I keep a chair by the door of the ward for him and he pretends not to see it."`, yurbin: `"Mac drags things in from outside the wire and sticks them under his lens like they're a gift, and he honestly doesn't understand why I'd rather he washed his hands first. One day he's going to bring something home that bites back, and it'll be me stitching him up."`, estrada: `"Samuel will go hungry for his faith and call it nothing, so I slip a little more into his bowl when he isn't looking, and I'll keep doing it until he catches me and tells me off. Somebody ought to feed a man who spends his life feeding everyone else."`, achebe: `"Lucas is the one who comes down and sits with the sick at the end of the day, and he never asks me to hurry it along, so he's got my respect and a standing place at my table. I only wish he'd shout once in a while, because that quiet disappointed face of his is worse than any order."`, zulu: `"Toby takes the worst watches himself and then turns up at the ward half dead and tells me he's fine, and honestly I could shake him. Somebody's got to make that boy sleep, so I'll just keep dragging him in until he does."`, halloran: `"Roberta swears like a drunk and I'll be damned if she hasn't saved more of my patients than half my staff, because she'll fix a pump with a bent spoon if that's what it takes. I don't ask what's in the still behind the seed store, and I do take a little of it for the sterilising."`, iyer: `"Michelle looks at a person and sees what she can learn from them, and I won't have it, not in my ward and not anywhere I can stop it. She knows I'm watching, which is exactly how I want it."`, waititi: `"Hamond has more people at his table than he's got food for, and somehow nobody leaves it hungry, which I love him for, and I'm half sure I'll find out how he does it one day. That's the kind of house I want, loud and full, with every chair taken."` } },
  yurbin: {
    now: { fine: `"Oh, I'm brilliant, I'm completely brilliant, I've got things growing that I can't name and one that I really hope isn't growing back at me, and where did I put my, never mind, I'll find it when I stop needing it."`, spent: `"They've told me to sit still, which I'm doing, I'm doing it very badly, but the thing I brought back from out there is on the bench next to me and it's doing something with the light, so I'm not exactly resting, I'm resting near it."`, frayed: `"Sleep? No, I'm sleeping, I'm sleeping fine, it's just that every time I close my eyes I start sorting what I saw into columns, and then it's morning, and then it's, what was I saying, right, I'm fine."`, failing: `"It's only that I tire faster than I did, and my hands do a thing now that they didn't, which is a fascinating bit of data really, I've been writing down how it goes, or I was, I'll find the pencil."`, hurt: `"It looks worse than it is, and in my defence it was the most interesting thing I've ever been bitten by, so if they'd just let me back to the bench I could tell you exactly what it did to the, no, fine, I'll lie here, I'm lying here."` },
    colony: { good: `"Everyone's fed and walking about like they own the place, which is lovely, and it means nobody's watching what I'm doing out past the wire, so I'd say the colony's doing wonderfully and so am I."`, steady: `"We're getting by, which on the drills we'd have called a good winter, and getting by is a perfectly respectable place to stand while you wait for the soil to tell you something, I only wish it would hurry up and say it."`, hungry: `"I know, I know, the stores are thin, and the one thing that frightens me is that I keep looking at the plants out there and thinking, well, something here eats them, so why can't we, and that's not a sensible thought, but it's a thought."`, low: `"People have stopped looking up, haven't they, which I hate, because there's so much to look up at, you've no idea, give me an afternoon with any of them and a decent sample and I'd have them arguing about it again."`, dread: `"Whatever this is, it's not random, nothing here is random, it's got a pattern and a reason and a, hold on, I keep wanting to go and look at it, and I'm told that's exactly the wrong thing to want, so I'm telling you instead."`, grim: `"I helped with some of it, I won't pretend I didn't, and I told myself it was for the colony and for the work, and mostly it was, and I can't tell you which part wasn't, so please don't ask me to check."` },
    you: [`"You're the first person who's ever let me finish a sentence and then asked what the next one was, so whatever you want from the lab, you've got it, and if it's dangerous I'll tell you after."`, `"You decide and I find out, and that works, mostly, it's only when you've decided before I've found out anything that I go and sulk in the lab with the jars."`, `"I just don't understand why every answer from you starts with how this could go wrong, because things go wrong, that's how you learn what they were, and I'm starting to think you'd rather not know."`, `"I'm still here because the work is here, and the work doesn't care who signs the orders, so you can stop worrying that I'll go, and start worrying about what I do when nobody's checking."`],
    on: { solheim: `"Jane has never once asked me what a thing is, only whether it'll kill us, and I keep telling her that's the same question, and she keeps looking at me like I've said it in another language."`, dahl: `"Nolan counts my samples as if they're going to climb out and do him a mischief, which, fine, one did, once, but he checks the lock twice and I've never found it locked against anything that mattered."`, kovacs: `"I borrow Jeremy's tools and I do bring them back, and honestly the stuff growing on the handles is a compliment, it means they're warm, but he doesn't see it that way and he's right about his knees, I'm only, where was I."`, nakamura: `"Andrea tells me off in the doorway and then patches me up on the bench and then tells me off again, and it's the only time anyone's ever looked at me like they actually worry, so I do mean to be more careful, I do."`, estrada: `"Samuel talks to the crops and I've never been sure they don't answer him, and I'd love to sit in the beds with him one night, just listening, if he'd stop looking at me like I'm the blight."`, achebe: `"Lucas looks at me with that patient face when I've skipped a step, and I'd honestly rather he shouted, because I know what I did, I just can't make myself sorry in time."`, zulu: `"Toby goes out past the wire before he'll send anyone, and I once took him to see a thing that really was worth the trip, and he stood there with his rifle up and missed all of it, which is the saddest thing I've ever watched."`, halloran: `"Roberta can make a sampler out of a ration tin and a bit of the lander, and she swears at me the entire time, and I'd walk into the dark with her tomorrow because anything we found she'd fix, or hit."`, brandt: `"Lou looks at my readings and tells me what they mean in a breath, and he's right, which is irritating, and then he asks if I've eaten, which is worse, because I never have."`, waititi: `"Hamond eats whatever I bring him from outside the wire without even asking what it is, and either he's the bravest man here or he really, really trusts me, and I try not to think about which."` } },
  estrada: {
    now: { fine: `"I'm well, thank you for asking, and so are the beans, though they'd never tell you so till they flower."`, spent: `"I'm resting, like I was told, though I keep walking down to the fields to see how they've got on without me. They've done fine, and I'll own that stung a little."`, frayed: `"I'm not sleeping, if I'm honest, and I lie there with the wind on the wire going over what I'd do different. It'll pass in its season, folk say, and I'm trying to believe them."`, failing: `"I'm slower than I was, and I'd sooner you heard it from me than saw it in the rows. I'll work while my hands let me, and after that somebody younger can have the beds."`, hurt: `"I'm laid up, but it's mending, and they tell me I'll be back in the dirt before long. I just don't like other folk minding the plots while they're coming into leaf."` },
    colony: { good: `"Folk are eating well and sleeping easy, and that's all I ever ask of a place. I said thanks for it this morning, and I'll say it again tonight."`, steady: `"We're getting by on ground that never asked for us, and that's no small thing. Nobody's gone to bed hungry yet, and I'd like to keep it that way through the winter."`, hungry: `"The stores are low and everybody can feel it, so I think we ought to eat thinner first, all of us, before anybody's child or anybody's grandmother goes short. I'll take the smaller bowl myself if it helps people see it's fair."`, low: `"People have stopped looking up when they walk the yard, and that worries me more than an empty bin would. A hungry field you can plant, but folks who've given up, I don't know how you sow that."`, dread: `"The colony's gone quiet, and it's not the good kind of quiet. Folk keep to their doors after dark, and I've been praying more than I used to that whatever this is leaves us be."`, grim: `"I said yes to some of it when I should've said no, and I won't pretend I didn't. We're fed, but it sits at the table with us at every meal, and I don't know how many seasons it'll take to feel clean again."` },
    you: [`"You've been straight with me, and you've never once forgotten who gets hurt first, so I'll stand with you whatever comes. That's all a person can ask of whoever's in your chair."`, `"We get on fine, and I do the work you ask, because most of it's good work. Where I think you've got it wrong I'll tell you quietly, and I'd hope you'd sooner that than me keeping it to myself."`, `"I've got my doubts about you, and I'd sooner say it to your face. You've leaned on the weak when the strong could've carried it, more than once, and I haven't liked watching."`, `"I'll keep the fields going, because folk need feeding whoever's making the calls. But I don't do it for you any more, and I think you know that."`],
    on: { solheim: `"She carries more than anyone should, and I pray for her, though I doubt she'd thank me for it. I only wish she'd remember that some of what she counts were somebody's kin, and never got to argue."`, dahl: `"He locks everything twice and jokes about it, and I think the jokes are how he gets through the night. I like him better than he'd believe, even if I wish he'd trust folks a little more than he does."`, kovacs: `"He keeps the machines going on those knees, and he never complains, so I try to carry whatever I can for him without making a show of it. A man like that ought to be sat down and fed properly more often than he is."`, nakamura: `"She slips extra in my bowl on a fast day when she thinks I'm not looking, and I let her, because arguing would only hurt her. There's nobody I'd sooner have over a sick bed, and I tell her so when she'll hold still for it."`, yurbin: `"He brings me things from past the wire and says to try them, and I'm half afraid and half curious every time. He's got no fear in him, so somebody has to have some for the both of us."`, achebe: `"He doesn't raise his voice, and somehow that's what makes you straighten up and do better. I'd follow him into most things, because he's fair, and fair is the thing I trust most in a person."`, zulu: `"He takes the worst of the night watches himself so nobody else has to, and I wish he'd let the others carry a share. He's a good lad, and the good ones wear out before their time, like a field nobody ever rests."`, halloran: `"She'll fix anything with whatever's lying around, and she swears like a drover while she does it. I'd sooner not know what's going on behind the seed store, but I'll say this for her, she's never let me down when something broke."`, brandt: `"He tells me I can't afford my fasts, and he's probably right, and I keep them anyway. He's a hard man to sit across from, but he stays up with the dying, and that tells me what he's really made of."`, iyer: `"She asked me to hand over seed lines for her trials, and I told her no, and I'd tell her again. Folks aren't a cost to me, and I don't think I'll ever sit easy at a table with somebody who sees them that way."` } },
  achebe: {
    now: { fine: `"I'm good, honestly. The folks are doing their jobs and I'm doing mine, and that's about all a man can ask for. How are you holding up? I mean you, not the colony."`, spent: `"I'm all right, I'm just not any use to anybody right now, and that's what's eating me. They told me to rest and I'm resting, because that's the deal, but I don't like it one bit. Anything you need from me, you ask, all right?"`, frayed: `"Sleep? Sure, I'm sleeping fine. All right, that's not true, and I won't say it to your face. I lie there and go over it and over it, and I get up tired. I'm still doing the work, I want you to know that."`, failing: `"The clinic's been straight with me, so I'll be straight with you. I'm not going to get better from this, and I'd sooner you heard it from me than from the talk at muster. Here's the deal, I'll keep doing the job until I can't, and when I can't, I'll tell you."`, hurt: `"I'm laid up, that's all, and I'm a lousy patient, ask anybody. I'll be back on my feet and back at it, and in the meantime I need you to keep an eye on the folks for me. That's all I'm asking."` },
    colony: { good: `"Honestly? It feels good out there. People are fed, they're talking to each other at muster, and they're pulling their weight without being asked twice. I'd like to keep it that way, so let's not get comfortable, all right?"`, steady: `"We're getting by, and I'm not going to dress it up as more than that. Folks are doing their jobs, nobody's going hungry, and nobody's celebrating either. It's a good solid day's work, and I'll take that."`, hungry: `"Our people are hungry, and they know it, and I'd be lying if I told them different. I won't do that. Here's what I think we do, we tell them the truth about the stores at muster, we share it out fair, and everybody takes the same short bowl, you and me included."`, low: `"Nobody's looking up. I walk through the yard and folks look at their boots. Listen, that's not on them, that's on us, and I think we need to go and stand in front of them and ask what they need, and then actually hear it."`, dread: `"People are dying and we don't know why, and I can't stand up at muster and tell them it's under control, because it isn't. So I'll tell them what we know, which isn't much, and what we're doing about it. They're scared, and they've every right to be, but they aren't stupid, and I won't treat them like they are."`, grim: `"I keep thinking about what I'd say at muster if I had to stand up and tell them everything we've done. I don't think I could do it. And if I couldn't say it to them, then we shouldn't have done it, and that's the part I can't get past, because I was in the room."` },
    you: [`"I'm with you, all the way, and I want you to hear me say it plainly. Whatever comes, you and I will take it on together, and the folks will see us do it. That's the deal as far as I'm concerned."`, `"We get along fine, you and I. You ask me before you tell me, mostly, and when you don't I'll say so and you listen. That's all I want out of working with somebody, and it's more than most people get."`, `"I need to ask you something straight, and I want you to answer it straight. Do you know what you're doing? Because some of what you've decided, I couldn't stand up at muster and explain, and that worries me. I'm giving you the chance to show me I'm wrong."`, `"I'm still here, and I'll tell you why. It's not for you, it's for our people. They need somebody who'll tell them the truth, and somebody has to hold this together. I gave you your second chance, and I'm sorry, but I'm not giving you another."`],
    on: { dahl: `"Nolan checks every lock twice, and I've stopped telling him to rest, because he doesn't hear it. I respect him, I really do. I just wish he'd believe somebody, someday, that the folks around him aren't out to get him."`, kovacs: `"Jeremy tells me how long a machine's got and he's never been wrong, so when he says it, I listen. I wish he'd listen to the clinic about his knees the same way. I told him so, plain, and he told me to mind my own business, and I said all right, but I'm going to ask again."`, nakamura: `"Andrea would walk through a wall for a patient, and she has, and I've had to talk to her about it. I'm not going to pretend I don't understand. But I need her to tell me before she goes over my head, not after, and I'll keep saying so until she does."`, yurbin: `"Mac is a good man and he loves the work, you can see it all over him. He'll walk right out past the wire after something new and not look back, though, and I keep telling him, you come home first, you show me you're coming home, and then you go back out. I don't think he hears me. I'll keep saying it."`, estrada: `"Samuel works hard and he never complains, and that's what bothers me. He goes short on his fast and does his shift anyway, and nobody's asked him if he's all right. I'm going to ask, and I'm not going to take fine for an answer."`, zulu: `"Toby's a good kid, and I say kid because he'd hate it. He takes the worst of the night watch himself so nobody else has to, and I love that about him, I do, but he's going to wear himself out. I need him on his feet, and I told him that."`, halloran: `"Roberta can fix anything with anything, and she'll tell you all about it, loudly, and I wouldn't change that. I do know about the still behind the seed store. Everybody does. I'm letting it go for now, because she's earned it, but she knows where I stand."`, brandt: `"Lou doesn't sugar anything, and some folks can't take it, but I'd sooner have the truth from him than a nice word from somebody else. He's sat up all night with our people more times than I can count. I trust him, plain and simple."`, iyer: `"Michelle's brilliant, I know that, and I don't doubt she'll get us answers. But I've heard how she talks about folks, like they're something to be spent, and I don't like it. I told her so. I need her to remember they're our people and not her materials."`, waititi: `"Hamond feeds everybody, and he'll make you laugh when you least feel like it, and I'm grateful for both. He promises more than we've got, though, and then has to stand up and own it. I tell him, Hamond, just say what's true the first time, it's easier on everyone. He says he will."` } },
  zulu: {
    now: { fine: `"I'm well, thank you for asking. The watch is on post, the wire's been walked, and I've nothing to report, which I'm glad of."`, spent: `"I'm resting, as ordered, and I haven't argued. It's hard to sit in the hall while my people stand a post that ought to be mine, but I understand why."`, frayed: `"I'm sleeping, yes. Well, not as much as I should, and I'd rather tell you that than have you hear it from someone else. It won't touch my duty, and if it does I'll say so first."`, failing: `"Permission to speak plainly? My health's going and it won't come back, I've been told so. I'm still fit to stand the watch for now, and I'll tell you the day I'm not."`, hurt: `"Who's hurt is me, I'm sorry to say, and it's my own fault for going out without enough eyes on the ground. The doctors say I'll mend, and I'd ask you not to give my post to anyone else, because I'll be back on it."` },
    colony: { good: `"First, everyone's fed. Second, nobody's been hurt on the watch in a good while, and I'd like to say that's the best report I've ever made you. I'm still walking the wire, though, in case."`, steady: `"We're getting by, and I'd say so without dressing it up. My people are tired but they're at their posts, and nobody's gone hungry that I know of."`, hungry: `"With respect, the watch is on short rations and it shows when they stand. I've given part of mine to the youngest of them, and I'd ask you not to stop me. Hungry people get slow and careless on a wire at night, and that's what I'm watching for."`, low: `"I'd rather not say it, but morale's very low. People don't talk at muster any more. I've told the watch to be gentle in the yard, and if there's trouble I'll go out to it myself first."`, dread: `"First, people are dying and I can't tell you what's doing it. Second, my watch is on the wire and they're frightened, and so am I, if you want it plain. I won't send one of them out into it without going myself."`, grim: `"I stood the watch for what was done. I didn't refuse, and I'll answer for that, but my people have to live next to it now, and some of them can't look at me."` },
    you: [`"You've never sent my people out on a guess, and you listen when I say no. I'd follow you anywhere you asked, and I'll say so in front of anyone."`, `"I do the work and you've been fair with me, and I'm grateful for that. When I disagree I'll say it to your face, with respect, and then I'll do what's decided."`, `"Permission to speak plainly. I'm not sure you count what your orders cost the people who carry them out, and I'll follow them, but I wanted you to hear that from me."`, `"I'll do my duty, understood. I'm staying at my post for the colony and for the people on the watch, and for no other reason, and you needn't expect more of me than that."`],
    on: { solheim: `"The commander has never once been wrong about what had to be done, and I've never once been easy about it. I'd stand any watch she gave me, but I wish she'd let my people see her feel the cost."`, kovacs: `"Jeremy's knees are finished and he won't sit down. I take his post at the yard when he's not looking, and he pretends not to know, which I'm grateful for."`, nakamura: `"Dr Tete has patched every one of my people and never asked whose fault it was. She shouts at me about my rota, and she's right to."`, yurbin: `"Mac goes out past the wire without telling me first, and he's so pleased with whatever he brings back. I'd like him to take an escort, and he'd like me to stop asking."`, estrada: `"Samuel keeps his fasts and I don't argue with a man's faith. I'd only ask him to eat when he's on the wire, because I can't have him fall at a post."`, achebe: `"Lucas gives a person a second chance, and I'd like to be worth one if I ever need it. He's never raised his voice at me, and that's worse than if he had."`, halloran: `"Roberta uses words in front of my younger people that I'd rather they didn't learn. She's also never once left a gate unmended when I asked, so I say nothing."`, brandt: `"Dr Chang has told me to stop taking the night watches. He's correct, and I'm sorry to say I haven't done it yet."`, iyer: `"The professor asked me for the loan of some of the watch and wouldn't say what for. I refused, and I'd refuse again, but I don't like not knowing why she wanted them."`, waititi: `"Hamond sends soup up to the cold posts, and my people talk about it for days after. I'd only ask him not to tell everyone what he hears at the wire, with respect."` } },
  halloran: {
    now: { fine: `"I'm fine, boss! Covered in shit to the elbows and I've not sat down since breakfast, but fuck it, that's a good day in my trade."`, spent: `"Rest, they said. Rest! I've been lying here going out of my bloody mind, boss. I rebuilt the kettle twice out of boredom, and it's a better fucking kettle now, so you're welcome."`, frayed: `"I'm fine. I'm FINE! Christ. I know I'm rattling on, I can hear it, but if I shut up I start thinking, and I'm not doing that, boss. Fuck that."`, failing: `"I'm knackered, boss, properly knackered, and it's not shifting. Hands still work, though! So don't you dare take me off the tools, because sitting about would finish me quicker than this shit will."`, hurt: `"Ah, it's nothing, I've had worse off a toaster! Just tell whoever's on my bench that if they move one piece of my shit I'll know, and I'll come down there on one leg and kick their arse."` },
    colony: { good: `"Everything works, boss! All of it! At the same fucking time! I don't know what to do with myself. So now's when we rip out the bodges and do them properly, while nothing's on fire. Don't look at me like that."`, steady: `"It's holding, boss, and that's the fucking problem! Half of it's wire and swearing and somebody's bootlace. Give me the plate and a month and I'll do it properly, and then you can lean on it."`, hungry: `"I can't machine dinner, boss! What I can tell you is the cold room's running on a bodge I'd be ashamed to sign, and when that shit goes the food goes with it. Let me fix it right before we lose the bloody lot."`, low: `"Everyone's got a face like a dropped pie and it's doing my fucking head in! I've tried jokes, I've tried shouting, I've tried taking the piss. Nothing! You can't fix that with a spanner, boss, and I hate it."`, dread: `"No jokes, boss, not about that. I want a wall between that thing and us, a proper one, and if you give me the plate I'll weld it myself tonight."`, grim: `"I built some of it, boss. I knew what it was for and I built it anyway, so no, I don't joke about it, and you don't get to either."` },
    you: [`"You let me do the job properly, boss! You've no idea how rare that is. Every other bastard wants it by supper and held on with tape. I'd wire a bomb for you, I swear to God. Don't ask me to."`, `"You're all right, boss. Bit too fucking fond of 'that'll do', and you pull that face when I say 'properly', but you're all right."`, `"You want it quick, I tell you quick means shit, you say quick anyway, shit breaks, and then you look at me like I broke it! That's your maths, boss, not mine. I've got witnesses."`, `"I'll fix what's broken because people need it, and none of this is their fault. That's it. That's all you get. Stay the fuck out of my workshop."`],
    on: { solheim: `"Jane scares the shit out of me, boss, and I'd still follow her off a cliff! Mind you, she'd have checked the cliff first, twice, and made me sign for it."`, dahl: `"Nolan reckons I'm stripping the lander. Of course I'm stripping the lander! It's got the only decent bearings on this whole fucking planet. Where does he think his gate hinges came from, the hinge fairy?"`, nakamura: `"Andrea'd square up to God himself over a patient, and she'd bloody win. I'd be right behind her, holding her coat and shouting."`, yurbin: `"Mac wants a rig to hold something that, his words, boss, 'mostly stays put'. Mostly! Fuck's sake, so I built it to hold something that doesn't, properly, triple-latched, and he looked a bit hurt."`, estrada: `"Samuel doesn't swear, doesn't shout, doesn't drink, so what the fuck do I do with that? He's a lovely man and I've absolutely no idea what to say to him."`, achebe: `"Lucas doesn't shout at you. He does this face, boss, this sad disappointed face, like you've pissed on his birthday cake. I'd pay good money to be shouted at."`, zulu: `"Toby's gone out past the wire himself again, the daft bastard! He's got a whole watch! Will somebody tell him he's allowed to send one of them?"`, brandt: `"Lou's ruder than me, boss, and he does it without one single swear word. Not one! How? It's fucking unnatural. I've been taking notes."`, iyer: `"Michelle asked me, dead polite, for a lock that only opens from the outside. From the outside, boss! Fuck that. I said I was busy. I'm going to stay busy till one of us dies."`, waititi: `"Me and Hamond have a still behind the seed store. You didn't hear that from me! You'll hear it from him by supper, the man can't keep his bloody mouth shut to save his life."` } },
  brandt: {
    now: { fine: `"Oh, good, you've come to ask whether the doctor is well. I'm perfectly well, which is a nuisance, because it leaves me free to worry about everybody else. Ask the question you actually came with."`, spent: `"I was sent out to be useful and came back to be told to lie down, so I'm lying down, under protest, and you should know that I make a terrible patient. You're not asking whether I'm rested. You're asking how soon you can send me out again."`, frayed: `"I'm not sleeping, since you're clearly going to ask, and before you write anything down, a tired doctor is still better than no doctor. If you want to know how long it can go on, I don't know, and I dislike saying so."`, failing: `"It's the slow kind, the kind I'd have told anyone else to put their affairs in order over. I've done the reckoning, and you'd like me to say it's nothing, and I'd like you to stop looking at me as though I were a chart, so we'll both go away disappointed."`, hurt: `"Marvellous, the physician has been made a patient, and not a good one. I'll mend, so you can put that face away. What you want to know is who's covering the ward while I lie here, and the answer is badly."` },
    colony: { good: `"Everyone's fed and nobody's weeping, so naturally I'm waiting for the bill. A quiet clinic usually means people are saving their troubles up, not that they've run out of them."`, steady: `"We're alive, which is the most that can honestly be said. I'd call it stable in the way a man balanced on a fence post is stable, and you'll notice nobody has asked me how long he can stand there."`, hungry: `"Thin people catch everything the well fed catch and keep it longer, and I can already see it in who comes through the door with a cough. You'll be asked to take a little from the strong to feed the weak, and you'll hate it. Do it anyway."`, low: `"Nobody's ill, exactly, they've just stopped being interested in getting better, and that's a symptom, not a mood. Treat it like one. Give them something to do that matters and a reason to be tired by evening."`, dread: `"I've had people through the ward whose deaths don't fit anything I was taught, and I keep writing down what I saw because I can't write down what it was. Whoever tells you it's under control hasn't been in the room, and can't tell you whether it passes from one to the next, which is the only question I care about."`, grim: `"We did what we said we had to, and I signed for some of it, so don't come to me for absolution. What I can tell you is that the clinic fills up with people who can't sleep, and there's nothing on my shelf for that I'd be willing to hand out."` },
    you: [`"You ask me before you decide, which is rarer than you'd think, and you listen when the answer is unpleasant. I'd say more, but you'd only get ideas."`, `"You do the job, you read what I send you, and you don't pretend to understand medicine. As patients go, that's about the best I could ask for."`, `"I'm still deciding whether you're careless or just frightened, because they look identical from the ward and want different treatment. You'd better find out which before I do."`, `"I stay because the people in that ward didn't choose you. Don't mistake my reports for loyalty, they're a duty, and I'll go on doing them with no illusions whatever."`],
    on: { solheim: `"She counts the dead in her head and believes nobody has noticed. I've noticed, and I'd call an honest ledger the most sensible thing she does. It's the sleeping she neglects."`, dahl: `"He checks every lock twice, and I've told him that's a symptom, and he's told me it's a lock. We're both right, which is why neither of us gives way, and why I rather like him."`, kovacs: `"I told him to his face the knees were finished, and he's been walking on them out of spite ever since. The spite is the best medicine he has, so I'm not going to take it off him."`, yurbin: `"He licks things. I'm not exaggerating, I've treated it. The man is delighted to be alive on a world that's trying to kill him, and I'd be happy to be less fond of him if he were less likely to go first."`, estrada: `"He fasts when the stores are low, I told him he can't afford it, and he thanked me for my concern in the voice of a man thanking a dog for barking. I'd call it faith if I were a different sort of doctor. As it is, I count his ribs."`, achebe: `"He doesn't shout, he just looks at you, and I've watched grown people confess to things they hadn't done to make it stop. I trust him because he gives a second chance and means it, which is more than I'd manage."`, zulu: `"He takes the worst of the night watches himself so the others can sleep, and I've told him to stop, and he nods, which is what people do instead of listening. He'll make a very fine dead hero if somebody doesn't sit him down."`, halloran: `"She's stripping the lander for parts and brewing something behind the seed store, and I'm in no position to object to either, since half of what I clean wounds with comes out of that still. I've asked her to label the bottles."`, iyer: `"She asked me once, in the most reasonable voice, how many people I thought a result might cost, and I'd like you to notice she asked me and not whether I'd mind. The answer is none. The question is the thing I'm treating."`, waititi: `"He promises more than the stores can give and then goes round apologising, and the apology is better medicine than most of what's on my shelves. I'd tell him so, but he can't keep a secret, and I have a reputation."` } },
  iyer: {
    now: { fine: `"I'm well, Administrator, in so far as the question has any bearing on the work, which I'd say it hasn't. If you're asking whether the laboratory is productive, then yes, provided that nobody interrupts it with enquiries of this kind."`, spent: `"I was sent out and I came back, which I'd count as the successful outcome. I've been told to rest and I'm resting, in the sense that I'm reading results rather than collecting them, and the difference between the two is smaller than whoever gave the order supposes."`, frayed: `"I'm sleeping adequately, and I'd ask you not to enter anything to the contrary in whatever record you keep. If my hands are less steady than they were, that is a matter for the work and not for conversation, and I would prefer to be judged on the work."`, failing: `"I'm aware of what the doctor has told you, Administrator, because I was told first and at some length. The condition is progressive, which is a fact about my instrument and not a reason to put it down, and I intend to use it for as long as it gives readings."`, hurt: `"I'm injured, and it will mend, so the only real loss is the time, and that I mean to recover by dictating to anyone who can hold a pen. You may send someone to take notes, provided it's someone who can follow them."` },
    colony: { good: `"It's well fed and in good heart, which is the ideal condition for a trial, since people who are comfortable tolerate a great deal more than they'd agree to when they are frightened. I would suggest that we use it to settle the questions whose answers we can put to work, while it lasts."`, steady: `"The colony is getting by, Administrator, which I'd describe as an adequate baseline and nothing more. A population with no pressing want has no particular reason to cooperate with anything asked of it, so I'd expect every request to cost us more now than it did when people were hungry."`, hungry: `"The ration is short, and I'd observe that a shortage is a form of experiment already under way, whether we designed it or not. If there is to be a loss, I would prefer that it bought us something we can use, such as knowing what on this world can be eaten, which would at least make it a cost and not a waste."`, low: `"Morale is very poor, and I should say plainly that I find it less alarming than you probably do. People in that condition are compliant, so the question is only what we are prepared to ask of them while they are."`, dread: `"Something is killing them, Administrator, and I haven't yet established what, and until I have, nothing anyone does about it will be better than a guess. I'll need access to the cases, and I'd ask that nobody be in a hurry to bury them."`, grim: `"I'm aware of what has been done, and I would only say that I'm not the person to ask for an opinion on it, having supplied some of the reasoning. If you want to know whether the results were worth the cost, I can tell you they were, and I have the figures."` },
    you: [`"I'll say this once, Administrator, because I don't repeat myself. You are the first person I've worked under who weighs a cost honestly, and I'd follow that judgment wherever the data led, including where the others would refuse to."`, `"You make decisions, and the majority of them are defensible, which is more than I could say for most of the people who have held your position. I'll continue to supply what you ask for, provided you continue to ask for things that are useful."`, `"I have reservations about your judgment, and I would rather state them than have you discover them later. You allow sentiment into decisions that ought to be settled by the numbers, and the colony settles that account, Administrator, not you."`, `"I remain here, Administrator, because the work is here and the work is the only thing that I'd call mine. I'll no longer pretend that I'm waiting for you to improve, and I'd be grateful if you didn't ask me to."`],
    on: { solheim: `"Commander Haddy keeps a private tally of the dead, and I have never understood the purpose of it, since it changes nothing and informs nothing. In every other respect she's the one person here who will pay a price when it falls due, and I'd work with her on that basis."`, dahl: `"Mr Edney's suspicion is a useful instrument, Administrator, and I'd have no objection to it if he would point it somewhere other than at me. He checks every lock twice, and I would observe that he has never once asked me what I'd like locked."`, kovacs: `"Mr Donadini gives an honest estimate of how long a machine has left, and I'd value that in anyone. His knees are now giving an equally honest estimate of his own, and Dr Chang is right that he loses a good many working hours by refusing to sit down."`, nakamura: `"Dr Tete treats the person in front of her and nobody else, which is admirable in a surgeon and impossible in a colony. She has twice declined to release tissue to me on grounds I'd call sentimental, and I would be obliged if you'd remind her whose laboratory it is."`, estrada: `"Mr Barlow declined to spare me a single seed line for my trials, Administrator, and I'd ask you to consider what that refusal has cost us in knowledge. He fasts while the stores run low and calls it a virtue, whereas I would call it an unmeasured loss of working hours."`, achebe: `"Mr McMurray is fair, and I'll grant that, though his disappointment is the only sanction he has ever applied to me and it has produced no change whatever. I find him easy to work around, and I believe the arrangement costs neither of us anything we would miss."`, zulu: `"Mr O'Neal refused me the loan of part of the watch, and he would not hear my reasons, which I thought a poor way to conduct a decision. He goes out into the dark himself before he'll send anyone, and I'd note that this is a considerable waste of a trained man."`, halloran: `"Ms Craigie is very capable, Administrator, and I'd say she could be more so if she would stop saying every thought aloud with that vocabulary. I asked her for a door that opens only from the outside, and I'm told she'll get to it, and I am prepared to go on being told that for some while yet."`, brandt: `"Dr Chang is the one member of this company who reads me accurately, and I'd say that makes him the one I have to be careful with. He tells the truth and then sits up all night with the consequences, which I suppose is what we'd call a method, though not a productive one."`, waititi: `"Mr Shepherd cannot keep a confidence, and so I have arranged never to give him one. He's generous with his table and I take what's put in front of me, but I'd ask you to bear in mind that anything said within his hearing has been said to the whole colony."` } },
  waititi: {
    now: { fine: `"Oh, you've caught me with flour to the elbows, which is how you always catch me, and I wouldn't change it for the world! I'm fine, I'm better than fine, I had a second breakfast and I'm already planning the third."`, spent: `"Resting, they tell me, resting! I've been told to sit down by people half my size, and I'm doing it, but I've peeled a whole sack of roots sitting down, so don't say I'm not trying. It's a funny thing, you go out there and come back and everything tastes a little flat, but I'll get over it, I always do."`, frayed: `"Sleep? Ha, I sleep like a baby, which is to say I wake up every hour and scream. No, I'm all right, I'm only up late with the pots and my head goes round and round like a mule at a well. Don't tell anyone I said that, I mean it, though I'll probably tell them myself by supper."`, failing: `"It's the old engine, it's running down, and it's got a lot of nerve doing it when I've got so much left to cook! Don't look at me like that, my mother lived on spite and goat's cheese to a ridiculous age and I've got her stubbornness, if not her cheese, so I'll be out in the beds for as long as these legs say yes."`, hurt: `"Look at me, laid out like a loaf that didn't rise! They won't let me up, and I told everyone the soup is in the left pot and I hear it's in the right pot, so the whole colony is probably eating something I've never tasted. I'll mend, so go on, tell me what's happening out there, I'm dying of not knowing!"` },
    colony: { good: `"The tables are full and the hall is loud and I haven't had to ration a single laugh, and I'll tell you, that's the sound I came all this way to hear. Ha! Somebody even sent back a bowl and said thank you, and I nearly wept into the pot."`, steady: `"We're getting by, my friend, and getting by is a fine thing to be doing. It's bread and no cake, you understand, but nobody's looking at their neighbour's plate and I count that as a good sign. My uncle Tarek used to say a quiet kitchen was either very good or very bad, and I'm choosing very good."`, hungry: `"I'm not joking about this one. The pots are thin and I'm stretching what I've got, and the little ones eat first and I eat when there's something left and there's mostly not. Give me the stores and some luck and I'll find something, but I won't pretend with you."`, low: `"Ha, well, I tried a joke in the hall and it landed like a dropped tray, and that's when I knew. They're not eating the way people eat when they're all right. I'll keep cooking and keep talking, because quiet is worse, but you might come and sit down with them yourself one night."`, dread: `"Everybody's coming to me while I peel, because people tell the cook things, and what they're telling me I'd rather not carry. Doors shut early and nobody wants the end of the bench. I've stopped telling jokes at the table, which you'll know isn't like me, and I don't know what to say to them."`, grim: `"We did it, and I stood there with a ladle in my hand and let it be done, so don't think I'm lecturing you. Now people sit at the table and look at each other as if they're trying to remember who we were. I still cook for them, what else can I do, but the food tastes of it, and I'd give anything to say it doesn't."` },
    you: [`"Wherever you point, I'll bring a pot and a shovel and my big mouth, and the mouth's the most useful of the three, ask anybody! I've followed worse people for worse reasons, and there's nobody else I'd trust with the stores."`, `"You're all right, you really are, and I say that as a man with opinions about everything including soup. We don't always see it the same way and I've said so out loud in the hall, but I turn up and I cook and I do the work, and I've never had to hide from you."`, `"I'll be straight with you, which costs me, because I'd far rather be loved. I've seen some of what you decided and I lie awake chewing on it, and I'm still here, but I'm not saying yes to everything anymore."`, `"I'm not going to boom at you, my friend, I haven't got it in me today. I stay for the people and the beds, and for Dalia, who's going to wake up and ask me what I did, but I don't stay for you. You'll hear it from me first, which is more than most people get."`],
    on: { solheim: `"She's never laughed at one of my jokes, not once, and I've tried everything, a good one, a terrible one, one about her own boots. But she eats every bowl I send up, down to the scrape, and I take that as laughing, in her language."`, dahl: `"Nolan checks every lock twice, and I tell him I'd rather he checked a pot twice, since there's never anything in the locks and there's often something in the pots, ha! He's a bitter man with a good heart under the vinegar, and I've been trying to pickle that heart in something sweeter for ages."`, kovacs: `"Jeremy's knees are finished, everyone knows it, and he'll still carry things he shouldn't because he's too proud to let a fat man do it. I sneak him the good bread and he pretends it's what everybody gets, and neither of us says a word, which is the only time I ever manage it."`, nakamura: `"Andrea is a lioness in a lab coat, I'd follow her into anything and I'd also hide the good knives before she got there! She's shouted at me about my belly and my sugar and my heart, and every time she's right, and every time I thank her with pastry."`, yurbin: `"Mac brings me things from outside the wire to taste, and I know I shouldn't, my friend, I know, but he stands there so delighted with his dirty hands held out and I can't say no to that face. Ha! If I go green one morning, tell my wife I died for science and a very interesting root."`, achebe: `"Lucas doesn't shout, which is worse, because he looks at you with that long patient face and you want to confess to things you haven't even done. I confessed to the still twice just to make him stop. A fair man, a very fair man, and I'd still rather be shouted at."`, zulu: `"Toby takes the worst nights for himself and won't hear a word against it, so I send soup up to the watch and make sure his is the fullest pot, and I tell nobody it's the fullest, or I tell everybody, I forget. He's a good lad, and he'll wear himself to the bone if somebody doesn't fatten him up."`, halloran: `"Roberta! Ha! My partner in crime, we've a little something bubbling behind the seed store that everybody knows about and nobody mentions, and she swears like a dockhand and fixes anything with a spoon and a prayer. I'd trust her with my life and my last jar, and I don't say that lightly about the jar."`, brandt: `"Lou tells me I'm fat, which I know, I've got a mirror, I've also got a belly that arrives in the room before I do, ha! He's a hard old stick who sees right through me, and he's probably right about the sugar, so I'm avoiding him and sending him pie."`, iyer: `"She'd put seed in a dish before she'd put it in the ground, and I can't make her see the bowl at the end of it. She asked somebody for something, and I promised I wouldn't say who, and it was a lock that only opens from the outside, and oh, damn, I've said it, haven't I? Ha, forget I spoke!"` } },
};
LF.PROFILE = P;
/* What is said of one who is gone, in the plain voice of the file. */
const goneLine = o => o.left ? `${o.first} is gone from the colony.` : `${o.first} is dead.`;
const nowKey = (s, p) => LF.laidUp && LF.laidUp(s, p) ? 'hurt' : p.body < 40 ? 'failing' : p.mind < 45 ? 'frayed' : p.spent && p.spent > s.day ? 'spent' : 'fine';
const colonyKey = s => { const lean = LF.lean && LF.lean(s), heat = LF.heat ? LF.heat(s) : 0, grim = LF.hum ? LF.hum(s) < 25 : false;
  return s.res.food <= 0 || lean ? 'hungry' : heat >= 2 ? 'dread' : grim ? 'grim' : s.morale < 30 ? 'low' : s.morale >= 62 && !heat ? 'good' : 'steady'; };
const youKey = p => (p.loyal >= 75 ? 0 : p.loyal >= 45 ? 1 : p.loyal >= 25 ? 2 : 3);
/* The page. null for anyone who is not one of the twelve (a colonist promoted in an old save, a notable). */
LF.profile = function (s, p) {
  const D = p && p.key && P[p.key]; if (!D) return null;
  const f = LF.FILE[p.key] || {}, yrs = Math.floor((s.day || 0) / LF.YEAR);
  const where = p.orbit ? `Aboard the ${s.world ? s.world.ship : LF.SHIP}, keeping the ship.` : p.away ? 'Out past the wire with a party.' : '';
  const others = [];
  for (const seat of LF.SEAT_ORDER) { if (seat === p.seat) continue;
    const o = LF.officer(s, seat), g = !o && LF.lastHeld ? LF.lastHeld(s, seat) : null, q = o || g;
    if (!q || !q.key || !D.on[q.key]) continue;
    others.push({ id: q.id, key: q.key, name: q.name, first: q.first, seat: LF.SEATS[seat].name, seatKey: seat, gone: !o, line: o ? D.on[q.key] : goneLine(q) }); }
  return { key: p.key, name: p.name, title: LF.title(p), seat: LF.SEATS[p.seat].name, age: f.age ? f.age + yrs : null, from: f.from || '', record: f.record || [],
    normal: p.nature || '', where, nowKey: nowKey(s, p), now: p.orbit ? '' : D.now[nowKey(s, p)], colonyKey: colonyKey(s), colony: D.colony[colonyKey(s)],
    youKey: youKey(p), you: D.you[youKey(p)], standing: LF.standing ? `${p.first} ${LF.standing(p)}.` : '',
    sore: p.sore && p.loyal < 45 && s.day - p.sore.d < 240 ? p.sore.t : '', bonds: LF.bondLine ? LF.bondLine(s, p) : '', others };
};
})();
